    topic: $json.topic,
    audience: $json.audience,
    businessType: $json.businessType,
    language: $json.language,
    tone: $json.tone,
    length: $json.length
  }
}];

const response = $input.first().json;

let text =
  response.text ||
  response.output ||
  response.response ||
  response.content ||
  response.result ||
  "";

text = text.replace(/```json/g, "");
text = text.replace(/```/g, "");
text = text.trim();

// Convert escaped newlines into real newlines
text = text.replace(/\\n/g, "\n");

// Remove escaped quotes if needed
text = text.replace(/\\"/g, '"');

let parsed;

try {
  parsed = JSON.parse(text);
} catch (e) {
  return [
    {
      json: {
        error: e.message,
        raw_output: text
      }
    }
  ];
}

return [
  {
    json: parsed
  }
];

